 */
String.prototype.extarctInteger = function() {
  var arr = this.match(/[\-0-9]/g);
  if (Array.isArray(arr)) {
    if (arr[0] == '0') {
      return '0';
    } else if (arr[0] == '-') {
      if (arr[1] && arr[1] == '0') {
