      var data = { tagName: tag};

      var el = $('#tagIgnore');
      var add = !el.hasClass("selected");

      if (add) {
        data['add'] = 'add';
      } else {
        data['del'] = 'del';
      }

      data['csrf'] = csrf_token;

      $.ajax({
        url: "/user-filter/ignore-tag",
        type: "POST",
        dataType: "json",
