        return async (req, res, next) => {
            console.log("run overdie")
            if(!req.acceptFields) req.acceptFields = [];
            const id = req.params.id;
            const acceptFields = {};

            req.acceptFields.forEach(field => {
                acceptFields[field] = 1;
