                res.status(req.resultConstructor.hardCodeResult || req.resultConstructor.statusCodeSuccess).send({
                    code: req.resultConstructor.statusCodeSuccess,
                    [req.resultConstructor.dataFieldName]: {
                        a: 1
                    }
                });
            }
        }
    }
}

module.exports = Controller;

