      /*   --- Payload Header --- */
      var send_data = {};
      send_data.time = new Date();
      send_data.txnType = 'HMAC';
      send_data.lib = 'libcommonCrypto.dylib';
      send_data.method = 'CCHmac';
      send_data.trace = trace();
      send_data.artifact = [];

      /*   --- Payload Body --- */
      var data = {};
      data.name = "Key";
      var keyLength = args[2].toInt32();
      var raw_key = hexify(hexdump(args[1], {
        length: keyLength
      }));
      data.value = raw_key;
      data.argSeq = 2;
