'use strict';

const getDevServer = require('./getDevServer');

const {SourceCode} = require('../../BatchedBridge/NativeModules');

// Avoid requiring fetch on load of this module; see symbolicateStackTrace
let fetch;

import type {StackFrame} from './parseErrorStack';

function isSourcedFromDisk(sourcePath: string): boolean {
  return !/^http/.test(sourcePath) && /[\\/]/.test(sourcePath);
}

async function symbolicateStackTrace(
  stack: Array<StackFrame>,
): Promise<Array<StackFrame>> {
  // RN currently lazy loads whatwg-fetch using a custom fetch module, which,
  // when called for the first time, requires and re-exports 'whatwg-fetch'.
  // However, when a dependency of the project tries to require whatwg-fetch
  // either directly or indirectly, whatwg-fetch is required before
  // RN can lazy load whatwg-fetch. As whatwg-fetch checks
  // for a fetch polyfill before loading, it will in turn try to load
  // RN's fetch module, which immediately tries to import whatwg-fetch AGAIN.
  // This causes a circular require which results in RN's fetch module
  // exporting fetch as 'undefined'.
  // The fix below postpones trying to load fetch until the first call to symbolicateStackTrace.
  // At that time, we will have either global.fetch (whatwg-fetch) or RN's fetch.
  if (!fetch) {
    fetch = global.fetch || require('../../Network/fetch').fetch;
  }

  const devServer = getDevServer();
  if (!devServer.bundleLoadedFromServer) {
    throw new Error('Bundle was not loaded from the packager');
  }

  let stackCopy = stack;

  if (SourceCode.scriptURL) {
    let foundInternalSource: boolean = false;
    stackCopy = stack.map((frame: StackFrame) => {
      // If the sources exist on disk rather than appearing to come from the packager,
      // replace the location with the packager URL until we reach an internal source
      // which does not have a path (no slashes), indicating a switch from within
      // the application to a surrounding debugging environment.
      if (!foundInternalSource && isSourcedFromDisk(frame.file)) {
        // Copy frame into new object and replace 'file' property
        return {...frame, file: SourceCode.scriptURL};
      }

      foundInternalSource = true;
      return frame;
    });
  }

  const response = await fetch(devServer.url + 'symbolicate', {
    method: 'POST',
    body: JSON.stringify({stack: stackCopy}),
  });
  const json = await response.json();
  return json.stack;
}

module.exports = symbolicateStackTrace;

/**
 * Wifi
 * @author  <NAME>
 */
import Debug from 'debug';
import request from 'request';
import * as childProcess from 'child_process';
import _extend from 'util';

const debug = Debug('node-wifi-utils:Wifi');


/**
 * Wifi Utils
 */
export default class Wifi {
	static platform: String;
	static scanCmd: String;

	/**
	 * Scan surrounding WiFi access points
	 * @returns { Promise }
	 */
	static scan(): Promise {
		return new Promise((resolve, reject) => {
			if (!this.scanCmd) {
				return reject('Platform not supported');
			}

			debug('running command %s', this.scanCmd);
			childProcess.exec(this.scanCmd, _extend(process.env, {
				LANG: 'en'
			}), (err, stdout, stderr) => {
				if (err) {
					debug('error: %s', err);
					return reject(err);
				}
				debug('stdout: %s', stdout);
				debug('stderr: %s', stderr);
				return resolve(this.parseScan(stdout));
			});
		});
	}

	/**
	 * Returns geolocation using surrounding WiFi access points
	 * @returns { Promise }
	 */
	static location(): Promise {
		return this
			.scan()
			.then(this.locationFromAccessPoints);
	}

	/**
	 * Returns geolocation using surrounding WiFi access points
	 * @returns { Promise }
	 */
	static locationFromAccessPoints(accessPoints: Array): Promise {
		return new Promise((resolve, reject) => {
			let url = 'https://maps.googleapis.com/maps/api/browserlocation/json';
			url += '?browser=node-wifi-utils&sensor=true&wifi=';
			url += accessPoints.map((accessPoint) => {
				return [
					'mac:' + accessPoint.mac,
					'ssid:' + accessPoint.ssid,
					'ss:' + accessPoint.signal_level
				].join('|');
			}).join('&wifi=');

			request({
				method: 'POST',
				url: url,
				json: true
			}, (err, res, body) => {
				if (err) {
					return reject(err);
				}
				let location = {
					accuracy: body.accuracy,
					latitude: body.location.lat,
					longitude: body.location.lng
				};
				debug('location: %s', JSON.stringify(location));

				resolve(location);
			});
		});
	}
}

/**
 * @fileoverview The Process page that shows the compass and the anayltics of a process
 * @author <NAME>
 * @version 1.0.0
*/
import React from "react";
import { Tab, Nav } from 'react-bootstrap';
import Layout from "../components/layout";
import {getProcess} from "../graphql_utils/utils" 
import Graph from "../components/Graph";
import Compass from "../components/Compass"
import "../components/bootstrap.css"

/**
 * The Component that handles the display/tabbing between Compass and AnalyticsPage
 * holds all the logic in retrieving the process according to proces id stored in the url
*/
class Process extends React.Component {

  state = {        
    date_end: "",
    date_start: "",
    id: "",
    name: "",
    phases: [],
    updateComponent: ""
  }

  componentDidMount() {
    const id = this.props.location.pathname.replace(process.env.PROCESS_LINK,"").replace("/","")
    this.getProcessItems(id);
  }

  /**
   * @param {string} id of the process
   * makes an api request to retrieve all of the data of the process from the process ID
   * once the data is retrieved, change the state of the component
  */
  getProcessItems = (id) => {
    getProcess(id)
    .then((res) => {
      const {date_end, date_start, id, name, phaseids : { items }} = res.data.getProcess
      this.setState({
        date_end, 
        date_start, 
        id, 
        name, 
        phases: items,
        updateCount: 0
      })
    })
  }

  /**
   * @param {string} either "Compass" or "Graph", the components to refresh
   *  change the state of the component to refresh, when the person chooses a tab, the child component will make a new request to the api for the latest data
  */
  updateHandler = (updateComponent) => {
    this.setState({updateComponent})
  }

  render() {
    const { name,id } = this.state;
    return (
      <Layout>
        <h2 className="text-center">{name}</h2>
        <Tab.Container id="left-tabs-example" defaultActiveKey="compass">
          <Nav variant="pills" defaultActiveKey="compass" className="process-tabs">
            <Nav.Item className="tab">
              <Nav.Link eventKey="compass" onClick={()=>{ this.updateHandler("Compass")}}>Compass</Nav.Link>
            </Nav.Item>
            <Nav.Item className="tab">
              <Nav.Link eventKey="analytics" onClick={()=>{ this.updateHandler("Graph")}}>Analytics</Nav.Link>
            </Nav.Item>
          </Nav>
          <Tab.Content>
            <Tab.Pane eventKey="compass">
              {id && <Compass id={id} updateHandler={this.updateHandler} updateComponent={this.state.updateComponent === "Compass"}/>}
            </Tab.Pane>
            <Tab.Pane eventKey="analytics">
              {id && <Graph processId={id} updateHandler={this.updateHandler} updateComponent={this.state.updateComponent === "Graph"}/>}
            </Tab.Pane>
          </Tab.Content>
        </Tab.Container>
      </Layout>
    );
  }
}

export default Process;

(function (){

/** Scroll to current line when hash changes */
function hashchanged(){
  var line, name, elems;
  if((line = findLine()) != -1){
    if(elem = document.getElementById("line-" + line)){
      // Remove highlighted from everything
      var highligted = document.querySelectorAll(".highlight");
      for(var i = 0; i < highligted.length; i++)
        highligted[i].classList.remove("highlight");
      // Highlight the line
      elem.parentNode.classList.add("highlight");
      // Highlight the annotation set for the line
      var aset = document.getElementById("aset-" + line);
      aset.classList.add("highlight");
      window.scroll(0, findPosTop(elem) - window.innerHeight / 4.0);
    }
  } 
}

/** Add auxiliary string method for indexOf using regexp
 * Credits to: http://stackoverflow.com/a/274094
 */
String.prototype.regexIndexOf = function(regex, startpos){
  var indexOf = this.substring(startpos || 0).search(regex);
  return (indexOf >= 0) ? (indexOf + (startpos || 0)) : indexOf;
}

/** Add auxiliary string method for LastIndexOf using regexp
 * Credits to: http://stackoverflow.com/a/274094
 */
String.prototype.regexLastIndexOf = function(regex, startpos){
  if(!regex.global){
    var flags = "g" + (regex.ignoreCase ? "i" : "") + (regex.multiLine ? "m" : "");
    regex = new RegExp(regex.source, flags);
  }
  if(typeof (startpos) == "undefined") {
      startpos = this.length;
  } else if(startpos < 0) {
      startpos = 0;
  }
  var stringToWorkWith = this.substring(0, startpos + 1);
  var lastIndexOf = -1;
  var nextStop = 0;
  while((result = regex.exec(stringToWorkWith)) != null) {
      lastIndexOf = result.index;
      regex.lastIndex = ++nextStop;
  }
  return lastIndexOf;
}

/** Initialize the context menu */
function init_menu(){
  var pre = document.querySelector(".file-lines pre");
  // Show menu when text is clicked
  pre.addEventListener('click', function(e){
    // Abort if the target isn't a code node underneath
    if(e.target == pre) return;
    var links = []
    // Find the word clicked
    var s = window.getSelection();
    // If there's a selection, we don't show menu, so users can copy/paste things
    if(!s.isCollapsed) return;
    var offset = s.focusOffset;
    var text  = s.anchorNode.nodeValue;
    var start = text.regexLastIndexOf(/[^A-Z0-9_]/i, offset) + 1;
    var end   = text.regexIndexOf(/[^A-Z0-9_]/i, offset);
    if(start == -1) start = 0;
    if(end   == -1) end   = text.length;
    var word = text.substr(start, end - start);
    // Make work link
    if(word.length > 0){
      links.push({
        icon:   'search', 
        text:   "Search for \"" + htmlEntities(word) + "\"",
        title:  "Search for documents with the substring \"" + htmlEntities(word) + "\"", 
        href:   wwwroot + "/search?tree=" + encodeURIComponent(dxr.tree()) + "&q=" + encodeURIComponent(word)
      });
    }
    // Append menu from target, if any
    if(e.target.dataset.menu){
      links = [].concat(links, JSON.parse(e.target.dataset.menu));
    }
    if(links.length == 0) return;
    // Populate and launch menu
    menu.populate(links);
    if(e.target.dataset.menu){
      menu.launch(e.target);
    }else{
      // Create a text range, and use it to get a bounding box
      // Our range will never cross elements, because we create it from
      // carat position, and when there's an actual non-empty selection
      // well, we can't really get the position of the click as text offset.
      var range = document.createRange();
      range.setStart(s.anchorNode, start);
      range.setEnd(s.anchorNode, end);
      var left = range.getBoundingClientRect().left;
      menu.launchAt(left, menu.posTop(e.target) + e.target.offsetHeight);
    }
    // Stop event propagation
    e.preventDefault();
    e.stopPropagation();
  }, false);
}

var pattern = /^#l[0-9]+$/;
/** Find line by anchor */
function findLine(){
  var result;
  if((result = pattern.exec(window.location.hash)) != null){
    return parseInt(result[0].substr(2));
  }
  return -1;
}

/** Find object position from the top */
function findPosTop(obj) {
  var top = 0;
  do{
    top += obj.offsetTop;
  }while(obj = obj.offsetParent);
  return top;
}

/** Find object position from the left */
function findPosLeft(obj) {
  var left = 0;
  do{
    left += obj.offsetLeft;
  }while(obj = obj.offsetParent);
  return left;
}

/** Initialize search tips */
function init_tip(){
  // Parse querystring for from=
  var query = null
  var items = window.location.search.substr(1).split("&");
  for(var i = 0; i < items.length; i++){
    var keyvalue = items[i].split("=");
    if(keyvalue[0] == "from")
      query = keyvalue[1];
  }
  if(query){
    // Set a nice search tip, so people can go the results
    var url = wwwroot + "/search?tree=" + dxr.tree() + "&q=" + query + "&redirect=false";
    text = ("You've been taken to a direct result " +
                     "<a href='{{url}}'>click here</a>" + 
                     " to see all search results").replace("{{url}}", url);
    dxr.setTip(text);
    // Insert the query into the search field
    var q = document.getElementById("query");
    q.value     = query;
    state.query = query;
    // Make search field redirect = false, untill user types a different query
    var redirect = document.getElementById("redirect");
    redirect.value = "false";
    q.focus();
    window.addEventListener('dxr-state-changed', function(){
      if(state.query != query)
        redirect.value = "true";
      else
        redirect.value = "false";
    }, false);
  }
}

/** Escape HTML Entitites */
function htmlEntities(str) {
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/** Hijack the blame link, to toggle blame annotations */
function hijackBlame(){
  var pc = document.getElementById("panel-content");
  var annos = document.getElementById("annotations");
  var blaming = false;
  // Helper for toggling the blame annotations
  function toggleBlame(){
    if(blaming)
      annos.classList.remove('blame');
    else
      annos.classList.add('blame');
    blaming = !blaming;
  }
  // Hijack click we think are hitting the blame link
  pc.addEventListener('click', function(e){
    // If the name is 'Blame'
    if(e.target.innerHTML != "Blame")
      return;
    // And it links to some sort of annotate
    var href = e.target.getAttribute('href');
    if(href.indexOf("/annotate/") == -1)
      return;
    // And it has the blame icon
    if(e.target.style.backgroundImage.indexOf("blame") == -1)
      return;
    // It's probably the blame link and we hijack it :)
    // I know this ugly, but short of allowing plugins to define
    // javascript and other bad things, there's no other way to integrate
    // tightly. Besides all the ugly stuff is in the template in javascript
    // and javascript can't be pretty anyway.
    // NOTE: While this is an ugly hack, the plugin and template interfaces
    // are fully respected, if we remove the blame specific things the
    // annotations still work, they just can't be toggled.
    e.preventDefault();
    e.stopPropagation();
    toggleBlame();
  }, true);

  // Get the info box
  var infobox = document.getElementById("info-box");

  // Handle clicks on note-blame annotations
  annos.addEventListener('click', function(e){
    if(e.target.classList.contains("note-blame")){
      // Stop what you're doing we've got a info-box to show
      e.preventDefault();
      e.stopPropagation();
      var data = e.target.dataset;
      var html = ""
       + "<img src='" + data.hgImg + "'>"
       + "<b>" + htmlEntities(data.hgUser) + "</b><br>"
       + "<i>" + dxr.prettyDate(data.hgDate) + "</i><br>"
       + e.target.getAttribute("title");
      infobox.innerHTML = html;
      infobox.style.display = 'block';
      infobox.style.top     = (menu.posTop(e.target) + e.target.offsetHeight) + "px";
      infobox.style.left    = menu.posLeft(e.target) + "px";
    }
  }, false);

  // Stop event to reaching window
  infobox.addEventListener('mousedown', function(e){
    e.stopPropagation();
  }, false);

  // Hide info when something is clicked
  window.addEventListener('mousedown', function(e){
    infobox.style.display = 'none';
  }, false);
}

/** Initialize everything */
window.addEventListener('load', function (){
  window.addEventListener('hashchange', hashchanged, false);
  init_tip();
  init_menu();
  hijackBlame();
  setTimeout(hashchanged, 0);
}, false);

}());

